CREATE OR REPLACE FORCE EDITIONABLE VIEW "PPPT"."COMP_PUESTO_PERSONA" ("IDPERSONAL", "IDPUESTO", "PUESTO", "WAIS", "THERMAN", "SPRANGER", "HERMAN", "CLEAVER", "LIFO", "EXPERIENCIA", "ESCOLARIDAD", "TOTAL") AS 
  SELECT Compatibilidad.IdPersonal, Compatibilidad.IdPuesto, Puestos.Puesto, Compatibilidad.Wais, Compatibilidad.Therman, Compatibilidad.Spranger, Compatibilidad.Herman, Compatibilidad.Cleaver, Compatibilidad.LIFO, Compatibilidad.Experiencia, Compatibilidad.Escolaridad, Compatibilidad.Total FROM Compatibilidad INNER JOIN Puestos ON Compatibilidad.IdPuesto = Puestos.IdPuesto;
